import Lenis from '@studio-freight/lenis';
import scrollama from 'scrollama';
import gsap from 'gsap';

// Ініціалізація Lenis для плавного скролу
const lenis = new Lenis({
  smooth: true,
  lerp: 0.07, // Зменшити для швидшого згладжування (стандарт 0.1)
  wheelMultiplier: 1.2, // Збільшити для чутливішого скролу (стандарт 0.8)
  touchMultiplier: 2.2,
  infinite: false,
});

function raf(time) {
  lenis.raf(time);
  requestAnimationFrame(raf);
}
requestAnimationFrame(raf);

// Ініціалізація Scrollama
const scroller = scrollama();

scroller
  .setup({
    step: '.scroll-trigger', // Елементи, які анімуватимуться
    offset: 0.8, // Спрацьовує на 80% видимості
    once: false, // Повторна анімація при скролі вверх
  })
  .onStepEnter(({ element }) => {
    element.classList.add('visible');

    // Додатково анімувати через GSAP
    gsap.fromTo(
      element,
      { opacity: 0, y: 50 },
      { opacity: 1, y: 0, duration: 0.8, ease: 'power3.out' }
    );
  })

  .onStepExit(({ element }) => {
    element.classList.remove('visible');

    // Якщо потрібно повертати елемент у вихідний стан при скролі вверх
    gsap.to(element, { opacity: 0, y: 50, duration: 0.5 });
  });
